"""
WizardState — shared mutable state passed between all screens.
Each screen reads and writes fields here; the apply step consumes everything.
"""

from dataclasses import dataclass, field
from typing import Optional


@dataclass
class DetectedHardware:
    cpu_vendor: str = ""          # "intel" or "amd"
    cpu_model: str = ""
    iommu_groups: int = 0
    iommu_active: bool = False
    secure_boot: bool = False


@dataclass
class NICDevice:
    iface: str                    # e.g. "enp5s0"
    pci_address: str              # e.g. "0000:05:00.0"
    vendor_id: str                # e.g. "8086:15f3"
    description: str
    iommu_group: int
    group_isolated: bool          # True if no other devices share this group
    selected: bool = False


@dataclass
class GPUDevice:
    pci_address: str
    vendor_id: str
    description: str
    iommu_group: int
    group_isolated: bool
    driver: str = ""              # "nvidia", "amdgpu", "i915"


@dataclass
class WizardState:
    # --- Hardware detection results (populated by screen 1) ---
    hardware: DetectedHardware = field(default_factory=DetectedHardware)
    nics: list = field(default_factory=list)          # list[NICDevice]
    gpus: list = field(default_factory=list)          # list[GPUDevice]

    # --- User choices (populated by screens 2-5) ---
    selected_nics: list = field(default_factory=list) # list[NICDevice]
    gpu_passthrough: bool = False
    selected_gpu: Optional[object] = None             # GPUDevice or None
    install_looking_glass: bool = False

    # AppVM names the user chose to provision
    selected_appvms: list = field(default_factory=list)  # list[str]

    # --- Apply results (populated by screen 6) ---
    apply_errors: list = field(default_factory=list)  # list[str]
